"export interface DummyItem {
  id: string;
  name: string;
  message: string;
  createdAt: Date;
}

// In-memory model representation for demonstration
const dummyDatabase: DummyItem[] = [
  {
    id: "1",
    name: "Sample Item",
    message: "This is a dummy item from the MVC model layer",
    createdAt: new Date(),
  },
];

export const DummyModel = {
  getAll: (): DummyItem[] => {
    return dummyDatabase;
  },

  getById: (id: string): DummyItem | undefined => {
    return dummyDatabase.find((item) => item.id === id);
  },

  create: (name: string, message: string): DummyItem => {
    const newItem: DummyItem = {
      id: (dummyDatabase.length + 1).toString(),
      name,
      message,
      createdAt: new Date(),
    };
    dummyDatabase.push(newItem);
    return newItem;
  },
};
"

"import { Request, Response } from "express";
import { DummyModel } from "../models/dummy.model";

export const dummyController = {
  getDummy: (req: Request, res: Response) => {
    try {
      const items = DummyModel.getAll();
      res.status(200).json({
        success: true,
        message: "Dummy route working successfully!",
        data: items,
      });
    } catch (error) {
      res.status(500).json({
        success: false,
        message: "Internal Server Error",
        error: (error as Error).message,
      });
    }
  },

  createDummy: (req: Request, res: Response) => {
    try {
      const { name, message } = req.body;
      if (!name || !message) {
        return res.status(400).json({
          success: false,
          message: "Name and message are required fields",
        });
      }

      const newItem = DummyModel.create(name, message);
      res.status(201).json({
        success: true,
        message: "Dummy item created successfully",
        data: newItem,
      });
    } catch (error) {
      res.status(500).json({
        success: false,
        message: "Internal Server Error",
        error: (error as Error).message,
      });
    }
  },
};
"

"import { Router } from "express";
import { dummyController } from "../controllers/dummy.controller";

const router = Router();

// GET /api/dummy
router.get("/", dummyController.getDummy);

// POST /api/dummy
router.post("/", dummyController.createDummy);

export default router;
"

"import { Router, Request, Response } from "express";
import dummyRoutes from "./dummy.routes";

const router = Router();

// Health check endpoint
router.get("/health", (req: Request, res: Response) => {
  res.status(200).json({ status: "OK", timestamp: new Date().toISOString() });
});

// Dummy routes mounted on /dummy
router.use("/dummy", dummyRoutes);

export default router;
"

"import express, { Application, Request, Response } from "express";
import cors from "cors";
import apiRoutes from "./routes";

const app: Application = express();

// Middlewares
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Root route
app.get("/", (req: Request, res: Response) => {
  res.status(200).json({
    message: "Server is up and running!",
  });
});

// API Routes
app.use("/api", apiRoutes);

// 404 Handler
app.use((req: Request, res: Response) => {
  res.status(404).json({
    success: false,
    message: "Route not found",
  });
});

export default app;
"

"import dotenv from "dotenv";
import app from "./app";

// Load environment variables
dotenv.config();

const PORT = process.env.PORT || 5000;

app.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
"

